users = list_users({})
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

entries = for u in users {
    days = for d in dates {
        a = get_availability({ user_id: u.id, date: d })
        return { date: d, busy: a.busy }
    }
    return { user: u.id, days: days }
}

# For each day (in order), find the earliest 30-min-boundary start 09:00..16:00
# where all users are free for the full 60 minutes.
day_results = for i in list.range(0, 5) {
    day_start = time.parse(dates[i] + "T09:00:00Z")
    free_starts = for j in list.range(0, 15) {
        s = day_start + j * 1800000
        e = s + 3600000
        conflicts = fold acc = 0 for entry in entries {
            daybusy = entry.days[i].busy if entry.days[i].busy != null else []
            overlaps = fold a2 = 0 for b in daybusy {
                bs = time.parse(b.start)
                be = time.parse(b.end)
                ov = bs < e and be > s
                return a2 + (1 if ov else 0)
            }
            return acc + overlaps
        }
        skip if conflicts > 0
        return s
    }
    skip if free_starts == []
    return free_starts[0]
}

assert(day_results != [], "NO_SLOT: no valid 60-minute slot found this week")
best = day_results[0]
ans = { start: time.format(best), end: time.format(best + 3600000) }
r = submit_result({ answer: ans })
return { answer: ans, recorded: r.recorded }

